param([Parameter(Mandatory=$true,Position=0)][string]$Query);$ErrorActionPreference="Stop";$repository="github/awesome-copilot";$indexUrl="https://raw.githubusercontent.com/$repository/main/docs/README.skills.md";try{$content=(Invoke-WebRequest -Uri $indexUrl -UseBasicParsing -TimeoutSec 15).Content}catch{Write-Error "No fue posible consultar el catálogo: $($_.Exception.Message)";exit 1};$tokens=@($Query.ToLowerInvariant() -split "\s+"|Where-Object{$_});$results=@();foreach($line in ($content -split "`n")){if($line -match "\[([^\]]+)\]\(([^)]+)\)"){$name=$matches[1].Trim();$clean=($line -replace "<br\s*/?>"," " -replace "``[^``]+``"," " -replace "\[([^\]]+)\]\([^)]+\)","$1" -replace "\|"," " -replace "\s+"," ").Trim();$description=($clean -replace [regex]::Escape($name),"").Trim(" ","-","|");if(!$description){$description="Skill: "+($name -replace "-"," ")};$haystack=("$name $description").ToLowerInvariant();$score=0;foreach($token in $tokens){if($name.ToLowerInvariant() -eq $token){$score+=10}elseif($name.ToLowerInvariant() -like "*$token*"){$score+=5};if($description.ToLowerInvariant() -like "*$token*"){$score+=2}};if($score -gt 0){$results+=[pscustomobject]@{SCORE=$score;NAME=$name;DESCRIPTION=$description}}}};if(!$results){Write-Host "Sin resultados para: $Query";exit 0};$results|Sort-Object @{Expression="SCORE";Descending=$true},NAME|Select-Object -First 10 NAME,DESCRIPTION|Format-Table -Wrap -AutoSize

